/**
 * FIFO message queue. Messages are { id, key, payload }. A private sequence is
 * retained across requeues so a later message for the same key cannot overtake
 * an earlier retry. Messages for other keys remain available.
 */
const sequence = Symbol('queueSequence')

export function createQueue() {
  const entries = []
  const done = new Set()
  let nextSequence = 0

  function assignSequence(message) {
    if (message[sequence] === undefined) {
      Object.defineProperty(message, sequence, { value: nextSequence++ })
    }
    return message
  }

  return {
    enqueue(message) {
      entries.push(assignSequence({ ...message, attempts: message.attempts ?? 0 }))
    },
    dequeue() {
      for (let i = 0; i < entries.length; i++) {
        const candidate = entries[i]
        if (done.has(candidate.id)) continue

        const hasEarlierSameKey = entries.some((entry) =>
          !done.has(entry.id) &&
          entry.key === candidate.key &&
          entry[sequence] < candidate[sequence]
        )
        if (!hasEarlierSameKey) return entries.splice(i, 1)[0]
      }
      return null
    },
    ack(id) {
      done.add(id)
    },
    requeue(message) {
      entries.push(assignSequence(message))
    },
    pending() {
      return entries.filter((entry) => !done.has(entry.id))
    },
  }
}

