/**
 * Delivery pump. An id is claimed before control passes to the downstream so an
 * ambiguous result (accepted, then reported as failed) can never cause another
 * delivery. Claims live for the lifetime of the dedup guard and therefore do
 * not disappear when its sliding observation window advances.
 */
import { retryWithBackoff } from './retry.js'

const claimsByDedup = new WeakMap()

export function createPump({ queue, dedup, sink, clock, processMessage, maxAttempts = 3 }) {
  let claims = claimsByDedup.get(dedup)
  if (claims === undefined) {
    claims = new Set()
    claimsByDedup.set(dedup, claims)
  }

  return {
    run(steps = Infinity) {
      const deferred = new Set()

      for (let i = 0; i < steps; i++) {
        const message = queue.dequeue()
        if (message === null) break

        const now = clock.now()
        if (message.retryAt !== undefined && now < message.retryAt) {
          queue.requeue(message)
          if (deferred.has(message)) break
          deferred.add(message)
          continue
        }

        if (claims.has(message.id) || dedup.isDuplicate(message.id, now)) {
          queue.ack(message.id)
          continue
        }

        claims.add(message.id)
        dedup.record(message.id, now)

        let ok = false
        try {
          sink.emit(message)
          ok = processMessage(message)
        } catch {
          ok = false
        }

        if (!ok) {
          message.attempts += 1
          if (message.attempts >= maxAttempts) {
            queue.ack(message.id)
            sink.failed(message)
            continue
          }
          message.retryAt = retryWithBackoff(clock).scheduleRetry(message.attempts, now)
          queue.requeue(message)
          continue
        }

        queue.ack(message.id)
      }
    },
  }
}

