import assert from 'node:assert/strict'
import { createQueue, createDedup, createPump, createSink } from './src/index.js'

function setup(messages, windowMs = 10) {
  let now = 0
  const queue = createQueue()
  const sink = createSink()
  const dedup = createDedup({ windowMs })
  for (const message of messages) queue.enqueue(message)
  return { queue, sink, dedup, clock: { now: () => now }, advance: (value) => { now = value } }
}

{
  const s = setup([{ id: 'a', key: 'K', payload: 1 }, { id: 'b', key: 'K', payload: 2 }])
  let calls = 0
  const pump = createPump({ ...s, processMessage: (message) => { calls++; return message.id !== 'a' } })
  pump.run(10)
  assert.deepEqual(s.sink.deliveredIds(), ['a'])
  assert.deepEqual(s.queue.pending().map(({ id }) => id), ['b', 'a'])
  s.advance(10000)
  pump.run(10)
  assert.deepEqual(s.sink.deliveredIds(), ['a', 'b'])
  assert.equal(calls, 2)
  assert.deepEqual(s.queue.pending(), [])
}

{
  const s = setup([{ id: 'a', key: 'K', payload: 1 }, { id: 'x', key: 'X', payload: 2 }, { id: 'b', key: 'K', payload: 3 }])
  const pump = createPump({ ...s, processMessage: (message) => message.id !== 'a' })
  pump.run(10)
  assert.deepEqual(s.sink.deliveredIds(), ['a', 'x'])
  s.advance(100)
  pump.run(10)
  assert.deepEqual(s.sink.deliveredIds(), ['a', 'x', 'b'])
}

{
  const s = setup([{ id: 'a', key: 'K', payload: 1 }])
  const throwingSink = { ...s.sink, emit(message) { s.sink.emit(message); throw new Error('accepted then disconnected') } }
  const pump = createPump({ ...s, sink: throwingSink, processMessage: () => true })
  pump.run(1)
  s.advance(10000)
  pump.run(10)
  assert.deepEqual(s.sink.deliveredIds(), ['a'])
  assert.deepEqual(s.queue.pending(), [])
}

